"""Copy HoH combat obstacle/trap coordinates; no room targets or floor routes."""
from pathlib import Path
import argparse
import re
from generate_palace_floor_data import arguments

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "MechanicRuntime/Upstream/Modules/Global/DeepDungeon"
TARGET = ROOT / "Presets/HeavenOnHigh/Floor/HeavenOnHighFloorData.cs"
TERRITORIES = [770, 771, 772, 782, 773, 783, 774, 784, 775, 785]


def generate(check):
    source = (SOURCE / "LoadedFloors.cs").read_text(encoding="utf-8-sig")
    lines = [
        "// Generated by tools/generate_hoh_floor_data.py from MIT BMR coordinates.",
        "using System.Numerics;", "using MasterPlayer.Mechanics.PalaceOfTheDead;", "",
        "namespace MasterPlayer.Mechanics.HeavenOnHigh;", "",
        "internal static class HeavenOnHighFloorData", "{",
        "    internal static readonly Dictionary<(int FloorSet, byte Tileset), PalaceFloorRoom[]> Rooms = new()", "    {",
    ]
    count = 0
    for floorset in range(1, 11):
        block = source.split(f'["2.{floorset}"] = new(', 1)[1].split('["', 1)[0]
        tilesets = re.findall(r"new Tileset<Wall>\(\s*\[(.*?)\]\)", block, re.S)
        assert len(tilesets) == 2
        for tileset, text in enumerate(tilesets):
            lines += [f"        [({floorset}, {tileset})] =", "        ["]
            rows = [line.strip() for line in text.splitlines() if line.strip()]
            assert len(rows) == 25
            for row in rows:
                args = arguments(row.removeprefix("new(").removesuffix("),"))
                assert len(args) == 5
                center = args[0]
                if center != "default":
                    center = "new(" + re.fullmatch(r"new\(new\((.*?)\), .*?\)", center)[1] + ")"
                lines.append(f"            new({center}, {', '.join(args[1:])}),")
                count += 1
            lines.append("        ],")
    assert count == 500
    lines += ["    };", "", "    internal static readonly Dictionary<ushort, Vector2[]> Traps = new()", "    {"]
    source = (SOURCE / "TrapData.cs").read_text(encoding="utf-8-sig")
    trap_count = 0
    for territory in TERRITORIES:
        body = re.search(r"\{\s*" + str(territory) + r", \[(.*?)\]\}", source, re.S)[1]
        traps = re.findall(r"new\(([^)]+)\)", body)
        assert traps
        trap_count += len(traps)
        lines += [f"        [{territory}] =", "        ["]
        for i in range(0, len(traps), 4):
            lines.append("            " + ", ".join(f"new({t})" for t in traps[i:i + 4]) + ",")
        lines.append("        ],")
    lines += ["    };", "}", ""]
    text = "\n".join(lines)
    if check:
        if TARGET.read_text(encoding="utf-8") != text:
            raise SystemExit("HoH floor combat coordinates differ; regenerate.")
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_text(text, encoding="utf-8", newline="\n")
    print(f"{'Checked' if check else 'Generated'} HoH {count} rooms/{trap_count} trap points in {len(TERRITORIES)} territories.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    generate(parser.parse_args().check)
